import{_ as u,a0 as a,w as i,s as d,ao as s,I as p,x as t,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Ubuntu 14.04 裏面配置 chroot 環境 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 14.04 裏面配置 chroot 環境 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 14.04 裏面配置 chroot 環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 14.04 裏面配置 chroot 環境 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150114 How to Configure Chroot Environment in Ubuntu 14.04","title":"如何在 Ubuntu 14.04 裏面配置 chroot 環境","tag":"201502","desc":""},"relativePath":"201502/20150114 How to Configure Chroot Environment in Ubuntu 14.04.md","filePath":"[post].md"}'),h={name:"201502/20150114 How to Configure Chroot Environment in Ubuntu 14.04.md"};function c(l,o,b,m,f,g){const r=a("Link");return i(),d("div",null,[o[18]||(o[18]=s(`<h1 id="如何在-ubuntu-14-04-裏面配置-chroot-環境" tabindex="-1">如何在 Ubuntu 14.04 裏面配置 chroot 環境 <a class="header-anchor" href="#如何在-ubuntu-14-04-裏面配置-chroot-環境" aria-label="Permalink to “如何在 Ubuntu 14.04 裏面配置 chroot 環境”">​</a></h1><p>你可能會有很多理由想要把一個應用、一個用户或者一個環境與你的 linux 系統隔離開來。不同的操作系統有不同的實現方式，而在 linux 中，一個典型的方式就是 chroot 環境。</p><p>在這份教程中，我會一步一步指導你怎麼使用 chroot 命令去配置一個與真實系統分離出來的獨立環境。這個功能主要可以用於測試項目，以下這些步驟都在 <strong>Ubuntu 14.04</strong> 虛擬專用服務器(VPS)上執行。</p><p>學會快速搭建一個簡單的 chroot 環境是一項非常實用的技能，絕大多數系統管理員都能從中受益。</p><h3 id="chroot-環境" tabindex="-1">Chroot 環境 <a class="header-anchor" href="#chroot-環境" aria-label="Permalink to “Chroot 環境”">​</a></h3><p>一個 chroot 環境就是通過系統調用，將一個本地目錄臨時變成根目錄。一般所説的系統根目錄就是掛載點&quot;/&quot;，然而使用 chroot 命令後，你可以使用其它目錄作為根目錄。</p><p>原則上，任何運行在 chroot 環境內的應用都不能訪問系統中其他信息（LCTT譯註：使用 chroot 把一個目錄變成根目錄，在裏面運行的應用只能訪問本目錄內的文件，無法訪問到目錄外的文件。然而，運行在 chroot 環境的應用可以通過 sysfs 文件系統訪問到環境外的信息，所以，這裏有個“原則上”的修飾語）。</p><h3 id="chroot-環境的用處" tabindex="-1">Chroot 環境的用處 <a class="header-anchor" href="#chroot-環境的用處" aria-label="Permalink to “Chroot 環境的用處”">​</a></h3><blockquote><ul><li><p>測試一個不穩定的應用服務不會影響到整個主機系統。</p></li><li><p>就算使用 root 權限做了些不當的操作，把 chroot 環境搞得一塌糊塗，也不會影響到主機系統。</p></li><li><p>可以在你的系統中運行另外一個操作系統。</p></li></ul></blockquote><p>舉個例子，你可以在 chroot 環境中編譯、安裝、測試軟件，而不去動真實的系統。你也可以<strong>在64位環境下使用 chroot 創建一個32位環境，然後運行一個32位的程序</strong>（LCTT澤注：如果你的真實環境是32位的，那就不能 chroot 一個64位的環境了）。</p><p>但是為了安全考慮，chroot 環境為非特權用户設立了非常嚴格的限制，而不是提供完整的安全策略。如果你需要的是有完善的安全策略的隔離方案，可以考慮下 LXC、Docker、vservers等等。</p><h3 id="debootstrap-和-schroot" tabindex="-1">Debootstrap 和 Schroot <a class="header-anchor" href="#debootstrap-和-schroot" aria-label="Permalink to “Debootstrap 和 Schroot”">​</a></h3><p>使用 chroot 環境需要安裝 <strong>debootstrap</strong> 和 <strong>schroot</strong>，這兩個軟件都在 Ubuntu 的鏡像源中。其中 schroot 用於創建 chroot 環境。</p><p><strong>Debootstrap</strong> 可以讓你通過鏡像源安裝任何 Debian（或基於 Debian 的）系統，裝好的系統會包含最基本的命令。</p><p><strong>Schroot</strong> 命令允許用户使用相同的機制去創建 chroot 環境，但在訪問 chroot 環境時會做些權限檢查，並且會允許用户做些額外的自動設置，比如掛載一些文件系統。</p><p>在 Ubuntu 14.04 LTS 上，我們可以通過兩步來實現這個功能：</p><h3 id="_1-安裝軟件包" tabindex="-1">1. 安裝軟件包 <a class="header-anchor" href="#_1-安裝軟件包" aria-label="Permalink to “1. 安裝軟件包”">​</a></h3><p>第一步，在Ubuntu 14.04 LTS 主機系統上安裝 debootstrap 和 schroot：</p><pre><code>$ sudo apt-get install debootstrap 
$ sudo apt-get install schroot
</code></pre><h3 id="_2-配置-schroot" tabindex="-1">2. 配置 Schroot <a class="header-anchor" href="#_2-配置-schroot" aria-label="Permalink to “2. 配置 Schroot”">​</a></h3><p>現在我們有工具在手，需要指定一個目錄作為我們的 chroot 環境。這裏創建一個目錄先：</p><pre><code>sudo mkdir /linoxide
</code></pre><p>編輯 schroot 的配置文件：</p><pre><code>sudo nano /etc/schroot/schroot.conf
</code></pre><p>再提醒一下，我們現在是在 Ubuntu 14.04 LTS 系統上。如果我們想測試一個軟件包能不能在 Ubuntu 13.10（代號是“Saucy Salamander”） 上運行，就可以在配置文件中添加下面的內容：</p><pre><code>[saucy]
description=Ubuntu Saucy
location=/linoxide
priority=3
users=arun
root-groups=root
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/schroot-config.png" alt=""></p><p>根據你的系統要求，調整上面的配置信息。</p><h3 id="_3-使用-debootstrap-安裝32位-ubuntu-系統" tabindex="-1">3. 使用 debootstrap 安裝32位 Ubuntu 系統 <a class="header-anchor" href="#_3-使用-debootstrap-安裝32位-ubuntu-系統" aria-label="Permalink to “3. 使用 debootstrap 安裝32位 Ubuntu 系統”">​</a></h3><p>Debootstrap 命令會在你的 <strong>chroot 環境</strong>裏面下載安裝一個最小系統。只要你能訪問鏡像源，你就可以安裝任何基於 Debian 的系統版本。</p><p>前面我們已經創建了 <strong>/linoxide</strong> 目錄用於放置 chroot 環境，現在我們可以在這個目錄裏面運行 debootstrap 了：</p><pre><code>cd /linoxide
sudo debootstrap --variant=buildd --arch amd64 saucy /linoxide/ http://archive.ubuntu.com/ubuntu/
sudo chroot /linoxide /debootstrap/debootstrap --second-stage
</code></pre>`,32)),p("p",null,[o[2]||(o[2]=t("你可以將 --arch 的參數換成 i386 或其他架構，只要存在這種架構的鏡像源。你也可以把鏡像源 ",-1)),e(r,{href:"http://archive.ubuntu.com/ubuntu/"},{default:n(()=>[...o[0]||(o[0]=[t("http://archive.ubuntu.com/ubuntu/",-1)])]),_:1}),o[3]||(o[3]=t(" 換成離你最近的鏡像源，具體可參考 ",-1)),e(r,{href:"https://launchpad.net/ubuntu/+archivemirrors"},{default:n(()=>[...o[1]||(o[1]=[t("Ubuntu 官方鏡像主頁",-1)])]),_:1}),o[4]||(o[4]=t("。",-1))]),o[19]||(o[19]=s(`<p><strong>注意：如果你是在64位系統中創建32位系統，你需要在上面第3行命令中加入 --foreign 選項，就像下面的命令：</strong></p><pre><code>sudo debootstrap --variant=buildd --foreign --arch i386 saucy /linoxide/ http://archive.ubuntu.com/ubuntu/
</code></pre><p>下載需要一段時間，看你網絡帶寬性能。最小系統大概有500M。</p><h3 id="_4-完成-chroot-環境" tabindex="-1">4. 完成 chroot 環境 <a class="header-anchor" href="#_4-完成-chroot-環境" aria-label="Permalink to “4. 完成 chroot 環境”">​</a></h3><p>安裝完系統後，我們需要做一些收尾工作，確保系統運行正常。首先，保證主機的 fstab 程序能意識到 chroot 環境的存在：</p><pre><code>sudo nano /etc/fstab
</code></pre><p>在文件最後面添加下面的配置：</p><pre><code>proc /linoxide/proc proc defaults 0 0
sysfs /linoxide/sys sysfs defaults 0 0
</code></pre><p>保存並關閉文件。</p><p>掛載一些文件系統到 chroot 環境：</p><pre><code>$ sudo mount proc /linoxide/proc -t proc
$ sudo mount sysfs /linoxide/sys -t sysfs
</code></pre><p>複製 /etc/hosts 文件到 chroot 環境，這樣 chroot 環境就可以使用網絡了：</p><pre><code>$ sudo cp /etc/hosts /linoxide/etc/hosts
</code></pre><p>最後使用 schroot -l 命令列出系統上所有的 chroot 環境：</p><pre><code>$ schroot -l
</code></pre><p>使用下面的命令進入 chroot 環境：</p><pre><code>$ sudo chroot /linoxide/ /bin/bash
</code></pre><p>測試安裝的版本：</p><pre><code># lsb_release -a
# uname -a
</code></pre><p>為了在 chroot 環境中使用圖形界面，你需要設置 DISPLAY 環境變量：</p><pre><code>$ DISPLAY=:0.0 ./apps
</code></pre><p>目前為止，我已經成功地在 Ubuntu 14.04 LTS 上安裝了 Ubuntu 13.10。</p><p>退出 chroot 環境：</p><pre><code># exit
</code></pre><p>清理一下，卸載文件系統：</p><pre><code>$ sudo umount /test/proc
$ sudo umount /test/sys
</code></pre><hr>`,27)),p("p",null,[o[6]||(o[6]=t("via: ",-1)),e(r,{href:"http://linoxide.com/ubuntu-how-to/configure-chroot-environment-ubuntu-14-04/"},{default:n(()=>[...o[5]||(o[5]=[t("http://linoxide.com/ubuntu-how-to/configure-chroot-environment-ubuntu-14-04/",-1)])]),_:1})]),p("p",null,[o[10]||(o[10]=t("作者：",-1)),e(r,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...o[7]||(o[7]=[t("Arun Pyasi",-1)])]),_:1}),o[11]||(o[11]=t(" 譯者：",-1)),e(r,{href:"https://github.com/bazz2"},{default:n(()=>[...o[8]||(o[8]=[t("bazz2",-1)])]),_:1}),o[12]||(o[12]=t(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:n(()=>[...o[9]||(o[9]=[t("wxy",-1)])]),_:1})]),p("p",null,[o[15]||(o[15]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[13]||(o[13]=[t("LCTT",-1)])]),_:1}),o[16]||(o[16]=t(" 原創翻譯，",-1)),e(r,{href:"http://linux.cn/"},{default:n(()=>[...o[14]||(o[14]=[t("Linux中國",-1)])]),_:1}),o[17]||(o[17]=t(" 榮譽推出",-1))])])}const _=u(h,[["render",c]]);export{C as __pageData,_ as default};
